/* vetai-counts.js — honest numbers (audit Batch B, items 12 + 25).
 *
 * Recomputes the displayed stats from the real data files / DOM at runtime
 * and populates the #nwGrid news cards with real publication dates and
 * specific source links from json/news.json. Dependency-free, defensive:
 * every step is wrapped so a failure leaves the true STATIC numbers in the
 * HTML untouched, and no element is touched when it is missing.
 *
 * Sources of truth:
 *  - articles:  keys of articles/manifest.json (123 standalone pages)
 *  - diseases:  sum of json/diseases/counts.json (generated by
 *               tools/gen-disease-counts.py from the 6 species files)
 *  - books:     rendered cards — #ownbGrid .ownb-card + #freeBooks .fbk
 *  - materials: the in-page EX array (EX + EXNEW + EXADD), falling back
 *               to the rendered #exchips .ex-chip subject buttons
 *  - news:      json/news.json items (status approved). Card mapping, in
 *               displayed order: [data-cat="alert"] cards take the unused
 *               `alert` items; [data-cat="research"] cards take the unused
 *               `research` items. Every card that gets a date/link wiring
 *               ALSO gets the matched item's own headline (title_ar) and
 *               summary (summary_ar), so the headline always describes the
 *               linked article. Cards with no matching item (tip / update
 *               / drugs) get the visible marker "بدون تاريخ موثّق" — never
 *               today's date presented as a publication date — and keep
 *               their static headlines untouched.
 */
(function () {
  'use strict';

  function setNum(id, n) {
    try {
      var el = document.getElementById(id);
      if (el && typeof n === 'number' && isFinite(n) && n > 0) el.textContent = String(n);
    } catch (e) { /* leave the static number in place */ }
  }

  function fetchJSON(url) {
    return fetch(url, { cache: 'no-cache' }).then(function (r) {
      if (!r.ok) throw new Error('HTTP ' + r.status);
      return r.json();
    });
  }

  /* ---------- item 12: stats ---------- */

  function countArticles() {
    fetchJSON('articles/manifest.json').then(function (d) {
      var n = 0;
      if (Array.isArray(d)) n = d.length;
      else if (d && typeof d === 'object') n = Object.keys(d).length;
      setNum('stat-articles', n);
      if (n > 0) applyResearchTitle(n);
    }).catch(function () { /* keep the static fallback */ });
  }

  function countDiseases() {
    fetchJSON('json/diseases/counts.json').then(function (d) {
      var n = 0;
      if (d && d.files && typeof d.files === 'object') {
        Object.keys(d.files).forEach(function (k) {
          var v = Number(d.files[k]);
          if (isFinite(v)) n += v;
        });
      } else if (d && typeof d.total === 'number') n = d.total;
      setNum('stat-diseases', n);
    }).catch(function () { /* keep the static fallback */ });
  }

  function countBooks() {
    try {
      var ownb = document.querySelectorAll('#ownbGrid .ownb-card').length;
      var free = document.querySelectorAll('#freeBooks .fbk').length;
      if (ownb > 0 || free > 0) setNum('stat-books', ownb + free);
    } catch (e) { /* keep the static fallback */ }
  }

  function countMaterials() {
    var n = 0;
    try {
      /* EX is a top-level const in an earlier classic script: the merged
         array (EX + EXNEW.ar + EXADD.ar). Access may throw if that script
         failed, so the DOM fallback below still applies. */
      if (typeof EX !== 'undefined' && EX && typeof EX.length === 'number') n = EX.length;
    } catch (e) { n = 0; }
    if (!(n > 0)) {
      try { n = document.querySelectorAll('#exchips .ex-chip').length; } catch (e2) { n = 0; }
    }
    setNum('stat-materials', n);
    setNum('qa-materials', n);
  }

  /* The sciLib RESEARCH entry "مقالات VetAI المفصلة — N مقالات سريرية
     متخصصة" is rendered lazily (tab switch / filter re-renders), so the
     rewrite below is idempotent and re-applied by a small observer. The
     literal in the RESEARCH array already carries the true value (123);
     this keeps it fresh when the manifest count changes. */
  var researchCount = 0;
  function applyResearchTitle(n) {
    researchCount = n;
    rewriteResearchTitle();
  }
  function rewriteResearchTitle() {
    if (!(researchCount > 0)) return;
    try {
      var host = document.getElementById('sciLib') || document;
      var heads = host.querySelectorAll('h4');
      for (var i = 0; i < heads.length; i++) {
        var h = heads[i];
        if (h.textContent.indexOf('مقالات VetAI المفصلة') === -1) continue;
        var next = h.textContent.replace(/مقالات VetAI المفصلة — \d+/, 'مقالات VetAI المفصلة — ' + researchCount);
        if (next !== h.textContent) h.textContent = next;
      }
    } catch (e) { /* rendered card absent: nothing to do */ }
  }
  function watchResearchTitle() {
    try {
      var host = document.getElementById('sciLib');
      if (!host || typeof MutationObserver === 'undefined') return;
      new MutationObserver(function () { rewriteResearchTitle(); })
        .observe(host, { childList: true, subtree: true });
    } catch (e) { /* observer unavailable: one-shot rewrite already ran */ }
  }

  /* ---------- item 25: news cards ---------- */

  var NO_DATE = 'بدون تاريخ موثّق';

  function fmtDate(iso) {
    try {
      var d = new Date(iso + 'T00:00:00');
      if (isNaN(d.getTime())) return null;
      var l = document.documentElement.lang || 'ar';
      if (l === 'ar') l = 'ar-DZ';
      try { return d.toLocaleDateString(l, { day: 'numeric', month: 'short', year: 'numeric' }); }
      catch (e) { return d.toLocaleDateString(); }
    } catch (e) { return null; }
  }

  function markTime(card, text, iso) {
    try {
      var t = card.querySelector('.nw-time');
      if (!t) return;
      t.textContent = text;
      /* data-vetai-date also tells the inline dates() helper to skip this
         element, so a later language toggle cannot restore a fake
         "today" date over a real one. */
      t.setAttribute('data-vetai-date', iso || 'none');
    } catch (e) { /* leave the element alone */ }
  }

  function setSourceLink(card, item) {
    try {
      var links = card.querySelectorAll('a.nw-more');
      for (var i = 0; i < links.length; i++) {
        var a = links[i];
        /* Only rewire links that already claim to be a source ("المصدر:").
           Action links ("اسأل المساعد", "اقرأ المزيد") keep their behavior. */
        if (a.textContent.indexOf('المصدر') !== 0) continue;
        if (item.source_url) a.setAttribute('href', item.source_url);
        a.textContent = 'المصدر: ' + (item.source_name || 'المصدر');
      }
    } catch (e) { /* leave the link alone */ }
  }

  /* Headline + summary follow the SAME matched item as the date/link,
     so a wired card can never show a static headline about a different
     story (e.g. an avian-influenza headline linking to a shamonda
     article). Only wired cards are touched; unwired cards keep their
     static text. title_ar/summary_ar are the populated fields in
     json/news.json (the _en fields are empty); fall back to _en if a
     future item ever carries only English text. */
  function setHeadline(card, item) {
    try {
      var h = card.querySelector('.nw-body h3');
      var title = item.title_ar || item.title_en;
      if (h && title) h.textContent = title;
      var p = card.querySelector('.nw-body p');
      var summary = item.summary_ar || item.summary_en;
      if (p && summary) p.textContent = summary;
    } catch (e) { /* leave the headline alone */ }
  }

  function populateNews() {
    var grid;
    try { grid = document.getElementById('nwGrid'); } catch (e) { return; }
    if (!grid) return;
    var cards;
    try { cards = grid.querySelectorAll('.nw-card'); } catch (e) { return; }
    if (!cards.length) return;

    function markAllUndated() {
      for (var i = 0; i < cards.length; i++) markTime(cards[i], NO_DATE, 'none');
    }

    fetchJSON('json/news.json').then(function (d) {
      var items = (d && d.items) || [];
      var approved = items.filter(function (it) { return it && it.status === 'approved'; });
      var byCat = { alert: [], research: [] };
      approved.forEach(function (it) {
        if (it.category === 'alert' || it.category === 'research') byCat[it.category].push(it);
      });
      var used = { alert: 0, research: 0 };
      for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var cat = card.getAttribute('data-cat');
        var item = null;
        if ((cat === 'alert' || cat === 'research') && used[cat] < byCat[cat].length) {
          item = byCat[cat][used[cat]++];
        }
        if (item && item.published) {
          var text = fmtDate(item.published);
          if (text) {
            markTime(card, text, item.published);
            setSourceLink(card, item);
            setHeadline(card, item);
            continue;
          }
        }
        markTime(card, NO_DATE, 'none');
      }
    }).catch(function () {
      /* No verified data available: never present today's date as a
         publication date. */
      markAllUndated();
    });
  }

  /* ---------- run ---------- */
  try { countArticles(); } catch (e) {}
  try { countDiseases(); } catch (e) {}
  try { countBooks(); } catch (e) {}
  try { countMaterials(); } catch (e) {}
  try { watchResearchTitle(); } catch (e) {}
  try { populateNews(); } catch (e) {}
})();
